1	export type Cell = [number, number];
2	
3	const MIN_LIVE_NEIGHBORS_FOR_SURVIVAL = 2;
4	const MAX_LIVE_NEIGHBORS_FOR_SURVIVAL = 3;
5	const LIVE_NEIGHBORS_FOR_REPRODUCTION = 3;
6	
7	type IsAlive = (cell: Cell) => boolean;
8	
9	export function nextGeneration(cells: Cell[]): Cell[] {
10	  const isAlive = livenessOf(cells);
11	  const survivors = cells.filter((cell) => survives(cell, isAlive));
12	  return [...survivors, ...bornCells(cells, isAlive)];
13	}
14	
15	function bornCells(livingCells: Cell[], isAlive: IsAlive): Cell[] {
16	  return reproductionCandidates(livingCells, isAlive).filter((cell) =>
17	    isBorn(cell, isAlive),
18	  );
19	}
20	
21	function livenessOf(cells: Cell[]): IsAlive {
22	  const living = new Set(cells.map(keyOf));
23	  return (cell) => living.has(keyOf(cell));
24	}
25	
26	function survives(cell: Cell, isAlive: IsAlive): boolean {
27	  const liveNeighbors = countLiveNeighbors(cell, isAlive);
28	  return (
29	    liveNeighbors >= MIN_LIVE_NEIGHBORS_FOR_SURVIVAL &&
30	    liveNeighbors <= MAX_LIVE_NEIGHBORS_FOR_SURVIVAL
31	  );
32	}
33	
34	function isBorn(cell: Cell, isAlive: IsAlive): boolean {
35	  return countLiveNeighbors(cell, isAlive) === LIVE_NEIGHBORS_FOR_REPRODUCTION;
36	}
37	
38	function reproductionCandidates(livingCells: Cell[], isAlive: IsAlive): Cell[] {
39	  const candidates = new Map<string, Cell>();
40	  for (const cell of livingCells) {
41	    for (const neighbor of neighborsOf(cell)) {
42	      if (!isAlive(neighbor)) {
43	        candidates.set(keyOf(neighbor), neighbor);
44	      }
45	    }
46	  }
47	  return [...candidates.values()];
48	}
49	
50	function neighborsOf([x, y]: Cell): Cell[] {
51	  const offsets = [-1, 0, 1];
52	  return offsets.flatMap((dx) =>
53	    offsets
54	      .filter((dy) => !(dx === 0 && dy === 0))
55	      .map((dy): Cell => [x + dx, y + dy]),
56	  );
57	}
58	
59	function countLiveNeighbors(cell: Cell, isAlive: IsAlive): number {
60	  return neighborsOf(cell).filter(isAlive).length;
61	}
62	
63	function keyOf([x, y]: Cell): string {
64	  return `${x},${y}`;
65	}
66

1	import { describe, expect, it } from "vitest";
2	import { type Cell, nextGeneration } from "./game-of-life.js";
3	
4	function asCellSet(cells: Cell[]): Cell[] {
5	  return [...cells].sort(([x, y], [otherX, otherY]) => x - otherX || y - otherY);
6	}
7	
8	describe("Game of Life -- nextGeneration", () => {
9	  it("returns no living cells for an empty input -- [] -> []", () => {
10	    expect(nextGeneration([])).toEqual([]);
11	  });
12	
13	  it("kills a single living cell with zero live neighbors (underpopulation) -- [[0,0]] -> []", () => {
14	    expect(nextGeneration([[0, 0]])).toEqual([]);
15	  });
16	
17	  it("kills both cells of a living pair, each having one live neighbor (underpopulation) -- [[0,0],[1,0]] -> []", () => {
18	    expect(nextGeneration([[0, 0], [1, 0]])).toEqual([]);
19	  });
20	
21	  it("keeps a living cell alive when it has exactly two live neighbors -- centre [1,0] of the blinker [[0,0],[1,0],[2,0]] survives", () => {
22	    expect(nextGeneration([[0, 0], [1, 0], [2, 0]])).toContainEqual([1, 0]);
23	  });
24	
25	  it("keeps a living cell alive when it has exactly three live neighbors -- every cell of the block [[0,0],[1,0],[0,1],[1,1]] survives, block is still life", () => {
26	    const block: Cell[] = [[0, 0], [1, 0], [0, 1], [1, 1]];
27	
28	    const next = nextGeneration(block);
29	
30	    expect(asCellSet(next)).toEqual(asCellSet(block));
31	  });
32	
33	  it("kills a living cell with more than three live neighbors (overpopulation) -- centre [1,1] of [[0,0],[1,0],[2,0],[0,1],[1,1]] dies", () => {
34	    expect(nextGeneration([[0, 0], [1, 0], [2, 0], [0, 1], [1, 1]])).not.toContainEqual([1, 1]);
35	  });
36	
37	  it("revives a dead cell with exactly three live neighbors (reproduction) -- [[0,1],[1,1],[2,1]] produces [1,0] and [1,2]", () => {
38	    const next = nextGeneration([[0, 1], [1, 1], [2, 1]]);
39	
40	    expect(next).toContainEqual([1, 0]);
41	    expect(next).toContainEqual([1, 2]);
42	  });
43	
44	  it("does not revive a dead cell with two live neighbors -- [[0,0],[2,0]] produces no living cell at [1,0]", () => {
45	    expect(nextGeneration([[0, 0], [2, 0]])).not.toContainEqual([1, 0]);
46	  });
47	
48	  it("does not revive a dead cell with four live neighbors -- [1,1] stays dead for [[0,0],[2,0],[0,2],[2,2]]", () => {
49	    expect(nextGeneration([[0, 0], [2, 0], [0, 2], [2, 2]])).not.toContainEqual([1, 1]);
50	  });
51	
52	  it("computes the full blinker oscillation -- horizontal [[0,1],[1,1],[2,1]] -> vertical [[1,0],[1,1],[1,2]]", () => {
53	    const next = nextGeneration([[0, 1], [1, 1], [2, 1]]);
54	
55	    expect(asCellSet(next)).toEqual(asCellSet([[1, 0], [1, 1], [1, 2]]));
56	  });
57	
58	  it("handles negative coordinates -- blinker [[-1,-1],[0,-1],[1,-1]] -> [[0,-2],[0,-1],[0,0]]", () => {
59	    const next = nextGeneration([[-1, -1], [0, -1], [1, -1]]);
60	
61	    expect(asCellSet(next)).toEqual(asCellSet([[0, -2], [0, -1], [0, 0]]));
62	  });
63	
64	  it.todo("returns each living cell only once -- no duplicate coordinates in the output for the glider [[1,0],[2,1],[0,2],[1,2],[2,2]]");
65	
66	  it.todo("does not mutate the input array -- input for [[0,0],[1,0],[2,0]] is unchanged after the call");
67	});
