  const prev = seen.get(k);
  if (prev && !(Object.is(prev[0],c[0]) && Object.is(prev[1],c[1]))) { collisions++; console.log("COLLISION", prev, c, k); }
  seen.set(k, c);
}
console.log("distinct-pair collisions:", collisions, "of", vals.length, "pairs");
